#include <cstdio>
#include <vector>
#include <cstring>

using namespace std;

typedef unsigned short ushort;

ushort dfs(int idx, int n, int l, vector<ushort>& arr, vector<ushort>& memo) {
    if (memo[idx] != 0xFFFF) return memo[idx]; // 0xFFFF represents uncomputed

    ushort lt = 0, rt = 0;
    if (arr[idx] < arr[idx - 1])
        lt = dfs(idx - 1, n, l, arr, memo);
    if (arr[idx] < arr[idx + 1])
        rt = dfs(idx + 1, n, l, arr, memo);

    return memo[idx] = max(lt, rt) + (l - arr[idx]);
}

int main(void) {
    int n, l;
    while (scanf("%d %d", &n, &l) == 2 && n) {
        vector<ushort> memo(n + 2, 0xFFFF);
        vector<ushort> arr(n + 2);
        memo[0] = 0;
        memo[n + 1] = 0;

        for (int i = 1; i <= n; i++) {
            scanf("%hu", &arr[i]);
        }
        arr[n + 1] = 0;

        ushort ans = 0;
        for (int i = 1; i <= n; i++) {
            ans = max(ans, dfs(i, n, l, arr, memo));
        }
        printf("%hu\n", ans);
    }
    return 0;
}

