#include <cstdio>
#include <vector>
#include <cstring>
#include <stack>

using namespace std;

typedef unsigned short ushort;

ushort iterative_dfs(int start, int n, int l, vector<ushort>& arr) {
    stack<pair<int, ushort>> s; // stack to hold (index, calculated_value)
    vector<ushort> memo(n + 2, 0xFFFF);
    s.push({start, 0});

    ushort max_value = 0;

    while (!s.empty()) {
        auto [idx, calc] = s.top();
        s.pop();

        if (memo[idx] != 0xFFFF) continue; // if already computed
        memo[idx] = calc + (l - arr[idx]);

        max_value = max(max_value, memo[idx]);

        if (arr[idx] < arr[idx - 1]) {
            s.push({idx - 1, memo[idx]});
        }
        if (arr[idx] < arr[idx + 1]) {
            s.push({idx + 1, memo[idx]});
        }
    }

    return max_value;
}

int main(void) {
    int n, l;
    while (scanf("%d %d", &n, &l) == 2 && n) {
        vector<ushort> arr(n + 2);
        arr[n + 1] = 0;

        for (int i = 1; i <= n; i++) {
            scanf("%hu", &arr[i]);
        }

        ushort ans = 0;
        for (int i = 1; i <= n; i++) {
            ans = max(ans, iterative_dfs(i, n, l, arr));
        }
        printf("%hu\n", ans);
    }
    return 0;
}

